# PY-231..PY-290: Dictionaries (lookups, counting, nested data, views and comprehensions, grouping and merging).
K = "Dictionaries"
NAMES = ["Asha", "Ravi", "Meena", "Kiran", "Sita", "Arun", "Divya", "Naveen", "Tara", "Om"]
ITEMS = ["pen", "ink", "book", "bag", "tape", "glue", "pad", "ruler"]


def pairs(r, names, lo, hi, kmin=3, kmax=7):
    k = r.randint(kmin, kmax)
    return [(n, r.randint(lo, hi)) for n in r.sample(names, k)]


def plines(ps):
    return [f"{a} {b}" for a, b in ps]


# ---- 15 basic key-value operations ----
py(K, "Phone Book Lookup", "A phone book stores `n` contacts as `name number`. Then `q` names are looked up. Print the number, or `Not found`, for each query.", "First line `n q`; then `n` lines `name number`; then `q` query names.", "One line per query.", "1 <= n, q <= 30",
   "n, q = map(int, input().split())\nbook = {}\nfor _ in range(n):\n    name, num = input().split()\n    book[name] = num\nfor _ in range(q):\n    print(book.get(input().strip(), \"Not found\"))",
   lambda r: (lambda ps, qs: rows(f"{len(ps)} {len(qs)}", *[f"{a} {r.randint(70000, 99999)}" for a, _ in ps], *qs))(pairs(r, NAMES[:6], 0, 0), r.sample(NAMES, r.randint(2, 4))), edges=["1 1\nAsha 123\nAsha\n"])
py(K, "Price List Update", "A shop's price list has `n` items. Then `m` updates `item price` arrive; an update changes the price if the item exists or adds the item if new. Print the final list sorted by item name as `item price` lines.", "First line `n m`, then `n` price lines, then `m` update lines.", "Sorted `item price` lines.", "1 <= n, m <= 20",
   "n, m = map(int, input().split())\nd = {}\nfor _ in range(n + m):\n    k, v = input().split()\n    d[k] = int(v)\nfor k in sorted(d):\n    print(k, d[k])", lambda r: (lambda a, b: rows(f"{len(a)} {len(b)}", *plines(a), *plines(b)))(pairs(r, ITEMS, 5, 90, 2, 5), pairs(r, ITEMS, 5, 90, 1, 4)), edges=["1 1\npen 5\npen 6\n"])
py(K, "Student Marks Report", "Marks are stored in a dictionary `name -> marks`. Given `n` students print the name of the topper and the average of all marks (two decimals) on one line.", "First line `n`, then `n` lines `name marks`.", "`topper average`.", "1 <= n <= 20",
   "n = int(input())\nm = {}\nfor _ in range(n):\n    a, b = input().split()\n    m[a] = int(b)\ntop = max(m, key=m.get)\nprint(top, f\"{sum(m.values()) / n:.2f}\")", lambda r: (lambda ps: rows(len(ps), *plines(ps)))(pairs(r, NAMES, 30, 100, 1, 7)), edges=["1\nAsha 50\n"])
py(K, "Remove Cancelled Orders", "An order book maps order ids to amounts. Given `n` orders and `m` cancelled ids, print the remaining orders sorted by id and the total remaining amount.", "First line `n m`, then `n` lines `id amount`, then `m` cancelled ids.", "Remaining `id amount` lines, then the total.", "1 <= n <= 20, 0 <= m <= 20",
   "n, m = map(int, input().split())\nd = {}\nfor _ in range(n):\n    k, v = input().split()\n    d[int(k)] = int(v)\nfor _ in range(m):\n    d.pop(int(input()), None)\nfor k in sorted(d):\n    print(k, d[k])\nprint(sum(d.values()))", lambda r: (lambda n: (lambda ids: (lambda m: rows(f"{n} {m}", *[f"{i} {r.randint(100, 900)}" for i in ids], *r.sample(ids, m)))(r.randint(0, min(3, n))))(r.sample(range(1, 30), n)))(r.randint(2, 6)), edges=["1 1\n1 5\n1\n"])
py(K, "Invert the Directory", "A directory maps names to roll numbers (all different). Print the inverted dictionary: `roll name` lines sorted by roll.", "First line `n`, then `n` lines `name roll`.", "Sorted `roll name` lines.", "1 <= n <= 20",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    a, b = input().split()\n    d[int(b)] = a\nfor k in sorted(d):\n    print(k, d[k])", lambda r: (lambda n: rows(n, *[f"{nm} {rl}" for nm, rl in zip(r.sample(NAMES, n), r.sample(range(1, 99), n))]))(r.randint(1, 7)), edges=["1\nA 5\n"])
py(K, "Check Keys and Values", "A config has `n` settings `key value`. Print `Yes` if the setting `key` exists, and on the next line `Yes` if any setting has value `value`, else `No`.", "First line `n`, then `n` settings, then a line `key value`.", "Two lines of `Yes`/`No`.", "1 <= n <= 20",
   "n = int(input())\ncfg = {}\nfor _ in range(n):\n    k, v = input().split()\n    cfg[k] = v\nk, v = input().split()\nprint(\"Yes\" if k in cfg else \"No\")\nprint(\"Yes\" if v in cfg.values() else \"No\")", lambda r: (lambda ks: rows(len(ks), *[f"{k} {r.choice(['on', 'off', '5'])}" for k in ks], f"{r.choice(['mode', 'speed', 'zzz', 'volume'])} {r.choice(['on', 'off', '9'])}"))(r.sample(["mode", "speed", "volume", "theme", "lang"], r.randint(2, 5))), edges=["1\na b\na b\n"])
py(K, "Roman Numeral Translator", "Using a dictionary of the symbols I=1, V=5, X=10, L=50, C=100, D=500, M=1000, convert a Roman numeral to a number (subtract when a smaller symbol comes before a larger one).", "One Roman numeral.", "The number.", "A valid numeral up to 3999.",
   "val = {\"I\": 1, \"V\": 5, \"X\": 10, \"L\": 50, \"C\": 100, \"D\": 500, \"M\": 1000}\ns = input().strip()\ntotal = 0\nfor i, ch in enumerate(s):\n    if i + 1 < len(s) and val[ch] < val[s[i + 1]]:\n        total -= val[ch]\n    else:\n        total += val[ch]\nprint(total)", lambda r: r.choice(["III", "IV", "IX", "LVIII", "MCMXCIV", "XL", "CDXLIV", "MMXXIV", "XIX", "DCCC"]) + "\n", edges=["I\n", "MMMCMXCIX\n"])
py(K, "Weekday Name from Number", "A calendar stores weekday names in a dictionary keyed by number 1 to 7 (1 = Monday). Print the name for the number, or `Invalid`.", "One integer.", "The name or `Invalid`.", "-10 <= n <= 20",
   "d = {1: \"Monday\", 2: \"Tuesday\", 3: \"Wednesday\", 4: \"Thursday\", 5: \"Friday\", 6: \"Saturday\", 7: \"Sunday\"}\nprint(d.get(int(input()), \"Invalid\"))", lambda r: f"{r.randint(-2, 10)}\n", edges=["1\n", "7\n", "0\n", "8\n"])
py(K, "Default Language Setting", "A profile has optional settings. Given a dictionary of `n` settings, print the value of `lang`, or `en` if it is missing, and the value of `theme`, or `light` if missing, on one line.", "First line `n`, then `n` lines `key value`.", "`lang theme`.", "0 <= n <= 10",
   "n = int(input())\nd = dict(input().split() for _ in range(n))\nprint(d.get(\"lang\", \"en\"), d.get(\"theme\", \"light\"))", lambda r: (lambda ks: rows(len(ks), *[f"{k} {r.choice(['hi', 'dark', 'te', 'blue'])}" for k in ks]))(r.sample(["lang", "theme", "font", "size"], r.randint(0, 4))), edges=["0\n"])
py(K, "Merge Two Wallets", "Two wallets map currency codes to amounts. Merge them by adding amounts of the same currency and print the result sorted by currency as `code amount` lines.", "First line `n m`, then `n` lines and `m` lines `code amount`.", "Sorted lines.", "1 <= n, m <= 10",
   "n, m = map(int, input().split())\nw = {}\nfor _ in range(n + m):\n    c, a = input().split()\n    w[c] = w.get(c, 0) + int(a)\nfor c in sorted(w):\n    print(c, w[c])", lambda r: (lambda a, b: rows(f"{len(a)} {len(b)}", *plines(a), *plines(b)))(pairs(r, ["INR", "USD", "EUR", "GBP", "JPY"], 1, 500, 1, 4), pairs(r, ["INR", "USD", "EUR", "GBP", "JPY"], 1, 500, 1, 4)), edges=["1 1\nA 1\nA 2\n"])
py(K, "Most Expensive Item", "From a menu of `n` dishes `name price` print the name and price of the dearest dish (the alphabetically first name if tied).", "First line `n`, then `n` lines.", "`name price`.", "1 <= n <= 20",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    a, b = input().split()\n    d[a] = int(b)\nbest = min(d, key=lambda k: (-d[k], k))\nprint(best, d[best])", lambda r: (lambda ps: rows(len(ps), *plines(ps)))(pairs(r, ["dosa", "idli", "vada", "poori", "upma", "pongal", "tea"], 20, 90, 1, 6)), edges=["1\na 5\n"])
py(K, "Update Marks by Bonus", "A teacher adds `b` bonus marks to everyone in the marks dictionary, capping at 100. Print the updated `name marks` lines in input order.", "First line `n b`, then `n` lines `name marks`.", "Updated lines.", "1 <= n <= 20",
   "n, b = map(int, input().split())\nd = {}\nfor _ in range(n):\n    a, m = input().split()\n    d[a] = int(m)\nfor k in d:\n    d[k] = min(100, d[k] + b)\n    print(k, d[k])", lambda r: (lambda ps: rows(f"{len(ps)} {r.randint(1, 15)}", *plines(ps)))(pairs(r, NAMES, 50, 100, 2, 6)), edges=["1 5\nA 99\n"])
py(K, "Pop the Oldest Ticket", "A support desk keeps tickets in a dictionary `id -> issue` in insertion order. Remove and print the most recently added ticket `id issue`, then print how many tickets remain.", "First line `n`, then `n` lines `id issue`.", "The removed ticket, then the count.", "1 <= n <= 20",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    k, v = input().split()\n    d[k] = v\nk, v = d.popitem()\nprint(k, v)\nprint(len(d))", lambda r: (lambda n: rows(n, *[f"{i} {r.choice(['login', 'bug', 'bill', 'slow'])}" for i in r.sample(range(100, 999), n)]))(r.randint(1, 6)), edges=["1\n1 a\n"])
py(K, "Setdefault Shopping Groups", "A shop groups items by their first letter. Given `n` items print each letter in alphabetical order with the items under it in input order, as `letter: item item`.", "First line `n`, then `n` items.", "One line per letter.", "1 <= n <= 30",
   "n = int(input())\ng = {}\nfor w in input().split():\n    g.setdefault(w[0], []).append(w)\nfor k in sorted(g):\n    print(f\"{k}: {' '.join(g[k])}\")", lambda r: (lambda n: rows(n, " ".join(r.choice(["apple", "avocado", "banana", "bread", "butter", "cake", "corn", "dates"]) for _ in range(n))))(r.randint(2, 10)), edges=["1\nz\n"])
py(K, "Copy then Change Inventory", "A branch copies the head-office stock (`item qty` lines) and sells `k` units of the first listed item. Print the branch stock and the head-office stock for that item as `branch head`.", "First line `n k`, then `n` lines `item qty`.", "`branch head`.", "1 <= n <= 10, k <= qty",
   "n, k = map(int, input().split())\nhead = {}\nfor _ in range(n):\n    a, q = input().split()\n    head[a] = int(q)\nbranch = dict(head)\nfirst = next(iter(head))\nbranch[first] -= k\nprint(branch[first], head[first])", lambda r: (lambda ps: rows(f"{len(ps)} {r.randint(0, 5)}", *[f"{a} {r.randint(5, 50)}" for a, _ in ps]))(pairs(r, ITEMS, 0, 0, 1, 5)), edges=["1 0\na 5\n"])
py(K, "Key With Lowest Value", "Fuel prices at `n` stations are stored as `station -> price`. Print the cheapest station and its price; if tied, the station that comes first in the input.", "First line `n`, then `n` lines `station price`.", "`station price`.", "1 <= n <= 20",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    a, b = input().split()\n    d[a] = int(b)\nk = min(d, key=d.get)\nprint(k, d[k])", lambda r: (lambda ps: rows(len(ps), *plines(ps)))(pairs(r, NAMES, 90, 110, 1, 6)), edges=["2\nA 5\nB 5\n"])

