py(K, "Bank Transfer Ledger", "Accounts start with balances. Then `t` transfers `from to amount` happen; a transfer is skipped if `from` lacks funds. Print the final balances sorted by account.", "First line `n t`, then `n` lines `account balance`, then `t` transfers.", "Sorted `account balance` lines.", "1 <= n <= 10",
   "n, t = map(int, input().split())\nb = {}\nfor _ in range(n):\n    a, v = input().split()\n    b[a] = int(v)\nfor _ in range(t):\n    f, to, amt = input().split()\n    amt = int(amt)\n    if b[f] >= amt:\n        b[f] -= amt\n        b[to] += amt\nfor a in sorted(b):\n    print(a, b[a])", lambda r: (lambda ns, t: rows(f"{len(ns)} {t}", *[f"{a} {r.randint(0, 500)}" for a in ns], *[f"{r.sample(ns, 2)[0]} {r.sample(ns, 2)[1]} {r.randint(1, 400)}" for _ in range(t)]))(r.sample(["A", "B", "C", "D"], r.randint(2, 4)), r.randint(1, 5)), edges=["2 1\nA 5\nB 0\nA B 5\n"])
py(K, "Product Catalogue Search", "A catalogue maps `category -> {product: price}` from lines `category product price`. A query line `category max_price` asks for products in that category costing at most `max_price`. Print them sorted by name, or `None`.", "First line `n`, then `n` lines, then the query line.", "Product names or `None`.", "1 <= n <= 30",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    c, p, v = input().split()\n    d.setdefault(c, {})[p] = int(v)\nc, m = input().split()\nres = sorted(p for p, v in d.get(c, {}).items() if v <= int(m))\nprint(*res if res else [\"None\"])", lambda r: (lambda n: rows(n, *[f"{r.choice(['toys', 'food'])} {nm} {r.randint(10, 200)}" for nm in r.sample(ITEMS, n)], f"{r.choice(['toys', 'food', 'cars'])} {r.randint(20, 200)}"))(r.randint(2, 7)), edges=["1\na b 5\na 4\n"])

# ---- 10 views and comprehensions ----
py(K, "Square Dictionary", "A teaching aid builds `{k: k*k}` with a dictionary comprehension for `k` from 1 to `n`. Print the pairs as `k:square` separated by spaces.", "One integer `n`.", "The pairs.", "1 <= n <= 30",
   "n = int(input())\nd = {k: k * k for k in range(1, n + 1)}\nprint(*(f\"{k}:{v}\" for k, v in d.items()))", lambda r: f"{r.randint(1, 20)}\n", edges=["1\n"])
py(K, "Filter Expensive Items", "From `n` lines `item price` use a dictionary comprehension to keep items priced above `p`. Print them sorted by name, or `None`.", "First line `n p`, then `n` lines.", "Lines `item price` or `None`.", "1 <= n <= 20",
   "n, p = map(int, input().split())\nd = {}\nfor _ in range(n):\n    a, b = input().split()\n    d[a] = int(b)\nres = {k: v for k, v in d.items() if v > p}\nif res:\n    for k in sorted(res):\n        print(k, res[k])\nelse:\n    print(\"None\")", lambda r: (lambda ps: rows(f"{len(ps)} {r.randint(10, 80)}", *plines(ps)))(pairs(r, ITEMS, 5, 100, 1, 6)), edges=["1 5\na 5\n"])
py(K, "Keys, Values and Items Views", "Given `n` lines `key value` (keys are distinct) print the keys sorted on line 1, the values sorted numerically on line 2 and the number of items on line 3.", "First line `n`, then `n` lines.", "Three lines.", "1 <= n <= 20",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    k, v = input().split()\n    d[k] = int(v)\nprint(*sorted(d.keys()))\nprint(*sorted(d.values()))\nprint(len(d.items()))", lambda r: (lambda ps: rows(len(ps), *plines(ps)))(pairs(r, NAMES, 1, 90, 1, 6)), edges=["1\na 1\n"])
py(K, "Zip Names to Marks", "Two lines give `n` names and `n` marks. Build a dictionary with `dict(zip(...))` and print `name=mark` pairs separated by spaces, in input order.", "First line `n`, then names, then marks.", "The pairs.", "1 <= n <= 20",
   "n = int(input())\nd = dict(zip(input().split(), input().split()))\nprint(*(f\"{k}={v}\" for k, v in d.items()))", lambda r: (lambda n: rows(n, " ".join(r.sample(NAMES, n)), " ".join(str(r.randint(30, 100)) for _ in range(n))))(r.randint(1, 6)), edges=["1\na\n1\n"])
py(K, "Swap Keys and Values Safely", "A dictionary of `name -> city` may have several names in the same city. Build `city -> sorted names` and print each city (sorted) as `city: n1 n2`.", "First line `n`, then `n` lines `name city`.", "One line per city.", "1 <= n <= 20",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    a, c = input().split()\n    d.setdefault(c, []).append(a)\nfor c in sorted(d):\n    print(f\"{c}: {' '.join(sorted(d[c]))}\")", lambda r: (lambda n: rows(n, *[f"{nm} {r.choice(['Pune', 'Goa', 'Agra'])}" for nm in r.sample(NAMES, n)]))(r.randint(2, 7)), edges=["1\nA B\n"])
py(K, "Discount Price Dictionary", "Apply a `d` percent discount to every price in a dictionary using a comprehension. Print `item newprice` (two decimals) in input order.", "First line `n d`, then `n` lines `item price`.", "Lines `item price`.", "1 <= n <= 20",
   "n, d = map(int, input().split())\nprices = {}\nfor _ in range(n):\n    a, b = input().split()\n    prices[a] = int(b)\nnew = {k: v * (100 - d) / 100 for k, v in prices.items()}\nfor k, v in new.items():\n    print(k, f\"{v:.2f}\")", lambda r: (lambda ps: rows(f"{len(ps)} {r.randint(5, 60)}", *plines(ps)))(pairs(r, ITEMS, 50, 900, 1, 5)), edges=["1 0\na 5\n"])
py(K, "Update With Latest Prices", "Old prices and new prices are two dictionaries. Use `update` so new prices override old ones and new items are added; print the merged dictionary sorted by item as `item price`.", "First line `n m`, then `n` old lines, then `m` new lines.", "Sorted lines.", "1 <= n, m <= 15",
   "n, m = map(int, input().split())\nold, new = {}, {}\nfor _ in range(n):\n    a, b = input().split()\n    old[a] = int(b)\nfor _ in range(m):\n    a, b = input().split()\n    new[a] = int(b)\nold.update(new)\nfor k in sorted(old):\n    print(k, old[k])", lambda r: (lambda a, b: rows(f"{len(a)} {len(b)}", *plines(a), *plines(b)))(pairs(r, ITEMS, 5, 90, 1, 5), pairs(r, ITEMS, 5, 90, 1, 4)), edges=["1 1\na 1\na 2\n"])
py(K, "Sort by Value Descending", "A scoreboard dictionary `player -> points` must be printed sorted by points (highest first) and by name when tied.", "First line `n`, then `n` lines `player points`.", "Sorted `player points` lines.", "1 <= n <= 20",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    a, b = input().split()\n    d[a] = int(b)\nfor k, v in sorted(d.items(), key=lambda t: (-t[1], t[0])):\n    print(k, v)", lambda r: (lambda ps: rows(len(ps), *plines(ps)))(pairs(r, NAMES, 1, 6, 2, 7)), edges=["1\na 1\n"])
py(K, "Dictionary Equality Test", "Two inventories are the same if they contain the same items with the same quantities, whatever the order. Print `Equal` or `Different`.", "First line `n m`, then `n` lines and `m` lines of `item qty`.", "`Equal` or `Different`.", "1 <= n, m <= 15",
   "n, m = map(int, input().split())\na = {}\nb = {}\nfor _ in range(n):\n    k, v = input().split()\n    a[k] = int(v)\nfor _ in range(m):\n    k, v = input().split()\n    b[k] = int(v)\nprint(\"Equal\" if a == b else \"Different\")", lambda r: (lambda a: (lambda b: rows(f"{len(a)} {len(b)}", *plines(a), *plines(b)))(r.sample(a, len(a)) if r.random() < .5 else a[:-1] + [(a[-1][0], a[-1][1] + 1)]))(pairs(r, ITEMS, 1, 9, 2, 5)), edges=["1 1\na 1\na 1\n"])
py(K, "Common Keys of Two Stores", "Two stores list prices as `item price`. Print the items sold by both, sorted, with the price difference (store 1 minus store 2) as `item diff`, or `None`.", "First line `n m`, then `n` lines and `m` lines.", "Lines or `None`.", "1 <= n, m <= 15",
   "n, m = map(int, input().split())\na = {}\nb = {}\nfor _ in range(n):\n    k, v = input().split()\n    a[k] = int(v)\nfor _ in range(m):\n    k, v = input().split()\n    b[k] = int(v)\ncommon = sorted(a.keys() & b.keys())\nif common:\n    for k in common:\n        print(k, a[k] - b[k])\nelse:\n    print(\"None\")", lambda r: (lambda a, b: rows(f"{len(a)} {len(b)}", *plines(a), *plines(b)))(pairs(r, ITEMS, 5, 90, 2, 5), pairs(r, ITEMS, 5, 90, 2, 5)), edges=["1 1\na 5\nb 6\n"])

