py(K, "Group Students by Grade", "Marks are graded `A` (90+), `B` (75-89), `C` (50-74), `F` (below 50). Print each grade that occurs, in the order A, B, C, F, followed by the sorted names, as `grade: names`.", "First line `n`, then `n` lines `name marks`.", "One line per used grade.", "1 <= n <= 20",
   "n = int(input())\ng = {}\nfor _ in range(n):\n    a, m = input().split()\n    m = int(m)\n    k = \"A\" if m >= 90 else \"B\" if m >= 75 else \"C\" if m >= 50 else \"F\"\n    g.setdefault(k, []).append(a)\nfor k in \"ABCF\":\n    if k in g:\n        print(f\"{k}: {' '.join(sorted(g[k]))}\")", lambda r: (lambda ps: rows(len(ps), *plines(ps)))(pairs(r, NAMES, 20, 100, 2, 8)), edges=["1\na 95\n"])
py(K, "Memoised Fibonacci", "A dictionary caches results so repeated work is avoided. Print the `n`-th Fibonacci number (F1 = F2 = 1) computed with a memo dictionary.", "One integer `n`.", "The Fibonacci number.", "1 <= n <= 90",
   "memo = {1: 1, 2: 1}\n\n\ndef fib(n):\n    if n not in memo:\n        memo[n] = fib(n - 1) + fib(n - 2)\n    return memo[n]\n\n\nprint(fib(int(input())))", lambda r: f"{r.randint(1, 90)}\n", edges=["1\n", "2\n", "90\n"])
py(K, "Two Sum With a Dictionary", "A cashier looks for two different coins that add up to `t` using a dictionary of seen coins. Print the 0-based indices `i j` (smallest `j` first found) or `None`.", "First line `n t`, then `n` coins.", "`i j` or `None`.", "2 <= n <= 100",
   "n, t = map(int, input().split())\nseen = {}\nfor j, c in enumerate(map(int, input().split())):\n    if t - c in seen:\n        print(seen[t - c], j)\n        break\n    seen[c] = j\nelse:\n    print(\"None\")", lambda r: (lambda k: rows(f"{k} {r.randint(5, 25)}", " ".join(str(r.randint(1, 15)) for _ in range(k))))(r.randint(3, 9)), edges=["2 4\n2 2\n"])
py(K, "First Unique Character", "A text editor finds the first character that appears only once in a string. Print it, or `None`.", "One string without spaces.", "The character or `None`.", "1 to 50 characters.",
   "s = input().strip()\nd = {}\nfor ch in s:\n    d[ch] = d.get(ch, 0) + 1\nfor ch in s:\n    if d[ch] == 1:\n        print(ch)\n        break\nelse:\n    print(\"None\")", lambda r: "".join(r.choice("aabbccdexyz") for _ in range(r.randint(2, 12))) + "\n", edges=["a\n", "aa\n"])
py(K, "Isomorphic Words", "Two words are isomorphic if letters of the first can be replaced one-to-one to give the second. Print `Yes` or `No` (same length required).", "Two words on two lines.", "`Yes` or `No`.", "1 to 30 letters.",
   "a = input().strip()\nb = input().strip()\nif len(a) != len(b):\n    print(\"No\")\nelse:\n    m, used, ok = {}, set(), True\n    for x, y in zip(a, b):\n        if x in m:\n            if m[x] != y:\n                ok = False\n        elif y in used:\n            ok = False\n        else:\n            m[x] = y\n            used.add(y)\n    print(\"Yes\" if ok else \"No\")", lambda r: r.choice([rows("egg", "add"), rows("foo", "bar"), rows("paper", "title"), rows("ab", "aa"), rows("abc", "abcd")]), edges=["a\nb\n"])
py(K, "Majority Vote by Region", "Lines `region candidate` are votes. For each region (sorted) print the winning candidate (ties go to the alphabetically first) as `region candidate`.", "First line `n`, then `n` lines.", "One line per region.", "1 <= n <= 30",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    reg, c = input().split()\n    d.setdefault(reg, {})\n    d[reg][c] = d[reg].get(c, 0) + 1\nfor reg in sorted(d):\n    v = d[reg]\n    print(reg, min(v, key=lambda k: (-v[k], k)))", lambda r: (lambda n: rows(n, *[f"{r.choice(['north', 'south'])} {r.choice(['Asha', 'Ravi', 'Meena'])}" for _ in range(n)]))(r.randint(2, 10)), edges=["1\nr c\n"])
py(K, "Cache Hits and Misses", "A small cache stores values by key. Process `n` lookups; if a key was seen before print `hit`, otherwise print `miss` and remember it. Finish with `hits misses`.", "First line `n`, then `n` keys.", "A line per lookup and a final summary.", "1 <= n <= 30",
   "n = int(input())\ncache = {}\nhits = misses = 0\nfor k in input().split():\n    if k in cache:\n        hits += 1\n        print(\"hit\")\n    else:\n        cache[k] = True\n        misses += 1\n        print(\"miss\")\nprint(hits, misses)", lambda r: (lambda n: rows(n, " ".join(r.choice(['a', 'b', 'c', 'd']) for _ in range(n))))(r.randint(2, 10)), edges=["1\na\n"])
py(K, "Student Enrolment Registry", "Commands manage a registry: `add name course` registers a student, `drop name` removes them, `count` prints the number of students. Process `n` commands and print the output of each `count`.", "First line `n`, then `n` commands.", "One number per `count`.", "1 <= n <= 40",
   "n = int(input())\nreg = {}\nfor _ in range(n):\n    p = input().split()\n    if p[0] == \"add\":\n        reg[p[1]] = p[2]\n    elif p[0] == \"drop\":\n        reg.pop(p[1], None)\n    else:\n        print(len(reg))", lambda r: (lambda n: rows(n, *[r.choice([f"add {r.choice(NAMES[:5])} c{r.randint(1, 3)}", f"drop {r.choice(NAMES[:5])}", "count"]) for _ in range(n - 1)], "count"))(r.randint(3, 12)), edges=["1\ncount\n"])
py(K, "Telephone Keypad Words", "A keypad dictionary maps digits to letters: 2=abc, 3=def, 4=ghi, 5=jkl, 6=mno, 7=pqrs, 8=tuv, 9=wxyz. Given a word of lower-case letters print the digits you would press.", "One lower-case word.", "The digit string.", "1 to 20 letters.",
   "pad = {\"2\": \"abc\", \"3\": \"def\", \"4\": \"ghi\", \"5\": \"jkl\", \"6\": \"mno\", \"7\": \"pqrs\", \"8\": \"tuv\", \"9\": \"wxyz\"}\nrev = {ch: d for d, letters in pad.items() for ch in letters}\nprint(\"\".join(rev[c] for c in input().strip()))", lambda r: r.choice(["hello", "python", "world", "code", "keypad", "zebra", "sms"]) + "\n", edges=["a\n", "z\n"])
py(K, "Inventory Reorder Report", "An inventory has `item qty reorder_level`. Print the items whose quantity is at or below their reorder level, sorted, with the shortfall `level - qty` as `item shortfall`, or `All stocked`.", "First line `n`, then `n` lines `item qty level`.", "Lines or `All stocked`.", "1 <= n <= 20",
   "n = int(input())\nres = []\nfor _ in range(n):\n    a, q, l = input().split()\n    if int(q) <= int(l):\n        res.append((a, int(l) - int(q)))\nif res:\n    for a, s in sorted(res):\n        print(a, s)\nelse:\n    print(\"All stocked\")", lambda r: (lambda n: rows(n, *[f"{nm} {r.randint(0, 40)} {r.randint(5, 30)}" for nm in r.sample(ITEMS, n)]))(r.randint(2, 6)), edges=["1\na 5 5\n", "1\na 6 5\n"])

