py(K, "Highest Rated Movie Per Genre", "Lines `genre movie rating` list movies. For each genre (sorted) print the movie with the highest rating (the alphabetically first if tied) as `genre movie`.", "First line `n`, then `n` lines.", "One line per genre.", "1 <= n <= 30",
   "n = int(input())\nd = {}\nfor _ in range(n):\n    g, m, r = input().split()\n    d.setdefault(g, []).append((-float(r), m))\nfor g in sorted(d):\n    print(g, min(d[g])[1])", lambda r: (lambda n: rows(n, *[f"{r.choice(['drama', 'action', 'comedy'])} {nm} {r.randint(10, 50) / 10}" for nm in r.sample(['m1', 'm2', 'm3', 'm4', 'm5', 'm6', 'm7', 'm8'], n)]))(r.randint(2, 8)), edges=["1\ng m 5\n"])
py(K, "Count Pairs With Same Difference", "Given `n` numbers, count pairs (i < j) whose difference `a[j] - a[i]` equals `k`, using a dictionary of counts.", "First line `n k`, then `n` integers.", "The number of pairs.", "1 <= n <= 100",
   "n, k = map(int, input().split())\ncnt = {}\ntotal = 0\nfor v in map(int, input().split()):\n    total += cnt.get(v - k, 0)\n    cnt[v] = cnt.get(v, 0) + 1\nprint(total)", lambda r: (lambda n: rows(f"{n} {r.randint(0, 5)}", " ".join(str(r.randint(1, 9)) for _ in range(n))))(r.randint(2, 10)), edges=["1 0\n5\n", "2 0\n5 5\n"])
py(K, "Employee ID Lookup With Validation", "Employees are stored as `id -> name`. Process `q` queries; for an id that exists print the name, for a missing one print `Unknown id <id>`, and if the id is not all digits print `Bad id`.", "First line `n q`, then `n` lines `id name`, then `q` queries.", "One line per query.", "1 <= n, q <= 20",
   "n, q = map(int, input().split())\nd = {}\nfor _ in range(n):\n    i, name = input().split()\n    d[i] = name\nfor _ in range(q):\n    x = input().strip()\n    if not x.isdigit():\n        print(\"Bad id\")\n    elif x in d:\n        print(d[x])\n    else:\n        print(\"Unknown id\", x)", lambda r: (lambda ids: rows(f"{len(ids)} 4", *[f"{i} {r.choice(NAMES)}" for i in ids], *[r.choice([str(r.choice(ids)), "999", "x1", str(r.choice(ids))]) for _ in range(4)]))(r.sample([101, 102, 103, 104, 105], r.randint(2, 4))), edges=["1 1\n1 A\n1\n"])
